mapper.update:
UPDATE ws_card
SET BALANCE_AMOUNT = BALANCE_AMOUNT - #{amountFen},
    UPDATE_BY = #{actorUserId},
    UPDATE_TIME = #{now}
WHERE ID = #{cardId}
  AND DATA_STATUS = 0
  AND CARD_STATUS = 1
  AND USER_ID = #{expectedOwnerUserId}
  AND (EXPIRE_TIME IS NULL OR EXPIRE_TIME = '' OR EXPIRE_TIME > #{now})
  AND BALANCE_AMOUNT >= #{amountFen}

UPDATE ws_card
SET BALANCE_ML = BALANCE_ML - #{planMl},
    UPDATE_BY = #{actorUserId},
    UPDATE_TIME = #{now}
WHERE ID = #{cardId}
  AND DATA_STATUS = 0
  AND CARD_STATUS = 1
  AND USER_ID = #{expectedOwnerUserId}
  AND (EXPIRE_TIME IS NULL OR EXPIRE_TIME = '' OR EXPIRE_TIME > #{now})
  AND BALANCE_ML >= #{planMl}

UPDATE ws_card
SET BALANCE_AMOUNT = BALANCE_AMOUNT + #{amountFen},
    UPDATE_BY = #{opUserId},
    UPDATE_TIME = #{now}
WHERE ID = #{cardId}
  AND DATA_STATUS = 0
  AND USER_ID = #{expectedOwnerUserId}

UPDATE ws_card
SET BALANCE_ML = BALANCE_ML + #{ml},
    UPDATE_BY = #{opUserId},
    UPDATE_TIME = #{now}
WHERE ID = #{cardId}
  AND DATA_STATUS = 0
  AND USER_ID = #{expectedOwnerUserId}
